    nightlifeShopping: ["Alsancak bar ve canlı müzik, Bostanlı daha mahalle, Urla bağ/uzun öğün ritmindedir. Kemeraltı'da nazar boncuğu, kahve, deri ve şarküteride kalite/üretim yeri; Kızlarağası'nda kahve yoğunluğunu bekleyin."],
    dayTrips: ["Efes–Selçuk başlı başına gün; Urla bağ/çarşı, Çeşme–Alaçatı, Eski Foça ayrı yönlerdir. Yaz hafta sonu Çeşme otoyolu ve Alaçatı parkı ciddi zaman kaybettirir; hafta içi/erken çıkın."], seasons: ["İlkbahar otlar ve yürüyüş, eylül deniz + şehir için iyi. Temmuz–ağustos sıcak ve kıyılar kalabalık; rüzgâr akşamı serinletebilir. Kış yağmurlu ama Kemeraltı ve yemek rotası için sakindir."], budget: ["Vapur ve raylı sistem ekonomik; Çeşme konaklama, Urla tadım menüsü ve araç maliyeti yükseltir. Efes için MüzeKart kapsamını ve Yamaç Evler gibi özel bölümleri güncel kontrol edin."], avoid: ["Kemeraltı'da kapanış sonrası ıssız sokaklara amaçsız girmeyin; gündüz gezin. Alaçatı'da menü/kuver/vale ücretini sorun. Efes'i öğle sıcağına bırakmayın."],
    places: [["Dostlar Fırını", "Alsancak", "Boyoz", "Erken sabah sade ve dolgulu boyoz çeşitlerini denemek için.", "Ekonomik"], ["Kemeraltı Bizim Lokanta", "Kemeraltı", "Ege ev yemekleri", "Otlar ve zeytinyağlıları esnaf öğleninde görmek için.", "Ekonomik"], ["Köfteci Mehmet Irak", "Kemeraltı", "İzmir köfte", "Çarşı içinde tek işe odaklanan klasik öğün.", "Orta"], ["Deniz Restaurant", "Alsancak", "Balık ve deniz ürünü", "Kordon yakınında ürün odaklı uzun akşam.", "Yüksek"], ["Reyhan Pastanesi", "Alsancak", "Pastane ve tatlı", "Şehrin eski pastane kültüründe mola.", "Orta"], ["Topçu", "Çankaya", "Çöp şiş ve klasikler", "Merkezde tarihî lokanta deneyimi.", "Orta"]],
    itinerary: [["1. Gün — Kemeraltı", "Konak–çarşı–han", "Agora ve müzeler", "Kordon gün batımı"], ["2. Gün — Körfez", "Alsancak", "Vapurla Karşıyaka/Bostanlı", "Yerel akşam"], ["3. Gün — Efes", "Erken Selçuk", "Efes ve müze", "İzmir'e dönüş"], ["4. Gün — Urla veya Foça", "Erken hareket", "Seçilen kıyı rotası", "Şehirde son akşam"]],
    practical: [["Vapur", "Körfez geçişini sadece ulaşım değil gezi olarak kullanın."], ["Efes saati", "Açılışa gidin, su ve şapka taşıyın."], ["Kıyı seçimi", "Çeşme, Urla ve Foça'yı aynı güne koymayın."], ["İZBAN", "Havaalanı yönünde trenin son varışını kontrol edin."]],
    faqs: [["İzmir kaç günde gezilir?", "Şehir için 2 gün; Efes ve bir kıyı günüyle 4 gün."], ["İzmir'de nerede kalınır?", "Gece için Alsancak, tarih için Konak, sakin yerel deneyim için Karşıyaka/Bostanlı."], ["İzmir'den Efes'e nasıl gidilir?", "Basmane'den bölgesel tren veya İZBAN+Selçuk bağlantısı; güncel seferi TCDD/İZBAN'dan doğrulayın."], ["İzmir'de araba gerekir mi?", "Şehir ve Efes için hayır; çoklu kıyı/bağ rotasında faydalı."]],
    related: [["Bodrum", "İzmir'den Bodrum'a Ege rotası", "Yarımada koyları ve gece."], ["Çanakkale", "Kuzey Ege'ye devam", "Troya, Bozcaada ve Dardaneller."], ["Muğla", "İzmir'den Gökova–Datça'ya", "Akyaka ve yavaş kıyı."], ["İstanbul", "İzmir–İstanbul şehir ikilisi", "Uçuş, otobüs veya tren+feribot bağlantıları."]], sourceName: "GoTürkiye — İzmir", sourceUrl: "https://goturkiye.com/tr/izmir", transportSource: { name: "İzmir Ulaşım", url: "https://www.eshot.gov.tr/" },
