    related: [["İstanbul", "Trabzon'dan İstanbul'a", "Uçuşla Boğaz ve büyük şehir."], ["Ankara", "Karadeniz'den Ankara'ya", "Başkent müzeleri."], ["Mardin", "Kuzeyden Mezopotamya'ya", "Taş şehir ve kültür kontrastı."], ["Çanakkale", "İki hafıza kıyısı", "Dardaneller, Troya ve Gelibolu."]], sourceName: "GoTürkiye — Trabzon", sourceUrl: "https://goturkiye.com/tr/trabzon", transportSource: { name: "Trabzon Havalimanı", url: "https://www.dhmi.gov.tr/Sayfalar/Havalimani/Trabzon/AnaSayfa.aspx" },
